#!/usr/bin/env bash
set -euo pipefail

# Regenerates lib/generated from the ARB files in lib/l10n. Run it after every ARB change and never edit
# lib/generated by hand. intl_utils writes 80 columns, so the output is formatted at the repository's 120 columns;
# the committed files are exactly what this script writes, and CI fails when they differ.
# Usage: scripts/generate_l10n.sh            (uses fvm)
#        DART=dart scripts/generate_l10n.sh  (uses the dart on PATH, as CI does)

DART="${DART:-fvm dart}"

cd "$(git rev-parse --show-toplevel)"
$DART run intl_utils:generate
$DART format lib/generated --line-length=120
